mapper.select:
        select 

        FROM REP_BOTTOM_ASSET


	        	AND (REP_ASSET_CODE IN 


						null) OR REP_ASSET_CODE IN  (

	        			#{item}

	        		)


	        	AND (REP_BOTTOM_CODE2 IN 


						null) OR REP_BOTTOM_CODE2 in (

	        			#{item}

	        		)


	        	AND REP_POSITION_DATE BETWEEN TO_DATE(#{repPositionDateStart},'YYYY-MM-DD') AND  TO_DATE(#{repPositionDateEnd},'YYYY-MM-DD')


	        	AND REP_STATUS_DATE BETWEEN TO_DATE(#{repStatusDateStart},'YYYY-MM-DD') AND  TO_DATE(#{repStatusDateEnd},'YYYY-MM-DD')


        	AND

        			 (REP_FINPROD_ID = #{item.repFinprodId} 
        			AND REP_ASSET_CODE = #{item.repAssetCode} 
        			AND REP_POSITION_DATE = TO_DATE(#{item.repPositionDate},'YYYY-MM-DD'))
